set-variable.value:
@{
if (!context.Request.Headers.ContainsKey("x-mosaic-cost-center")) { return ""; }
var values = context.Request.Headers["x-mosaic-cost-center"];
if (values == null || values.Length != 1 || values[0] == null) { return "!"; }
var code = values[0].Trim();
if (!System.Text.RegularExpressions.Regex.IsMatch(code, "^[A-Za-z0-9._-]\u007b1,64\u007d$")) { return "!"; }
return code.ToLowerInvariant();
}

when.condition:
@{
var headers = context.Request.Headers;
var query = context.Request.Url.Query;
string header = null;
string parameter = null;
if (headers.ContainsKey("Ocp-Apim-Subscription-Key")) {
    var values = headers["Ocp-Apim-Subscription-Key"];
    if (values == null || values.Length != 1 || String.IsNullOrWhiteSpace(values[0])) { return true; }
    header = values[0];
}
if (query.ContainsKey("subscription-key")) {
    var values = query["subscription-key"];
    if (values == null || values.Length != 1 || String.IsNullOrWhiteSpace(values[0])) { return true; }
    parameter = values[0];
}
if (header != null && parameter != null && !String.Equals(header, parameter, StringComparison.Ordinal)) { return true; }
return context.Subscription == null || String.IsNullOrEmpty(context.Subscription.Id);
}

set-variable.value:
@{
if (context.Subscription == null) { return ""; }
var subscription = context.Subscription.Id;
if (String.Equals(subscription, "mosaic-grant-1", StringComparison.OrdinalIgnoreCase)) { return "82d6717d52e846faa8a5a830f974695f21d0ff719cf9bda91e0caf223bd29a6b|general"; }
if (String.Equals(subscription, "mosaic-grant-2", StringComparison.OrdinalIgnoreCase)) { return "4c9af819b759b8e9dfc7e64407a727a42e576450a91bfa82d5951005521bc5d1|research"; }
if (String.Equals(subscription, "mosaic-grant-3", StringComparison.OrdinalIgnoreCase)) { return "3d7abb22194627137690dc4329c3f475e34c9c7009ad3844003942e743294467|sales.emea"; }
if (String.Equals(subscription, "mosaic-grant-4", StringComparison.OrdinalIgnoreCase)) { return "1e48c4bfb436743094bbb70de287bcd0bbdac045434f569c1472eaa769a05638|research"; }
if (String.Equals(subscription, "mosaic-grant-5", StringComparison.OrdinalIgnoreCase)) { return "-"; }
return "";
}

@{
var match = (string)context.Variables["mosaic-key-match"];
var bar = match.IndexOf('|');
return bar < 0 ? match : match.Substring(0, bar);
}

@{
var match = (string)context.Variables["mosaic-key-match"];
