when.condition:
@{
var values = context.Request.Headers["Authorization"];
if (values == null || values.Length != 1) { return true; }
var authorization = values[0];
return String.IsNullOrWhiteSpace(authorization) || !authorization.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase) || String.IsNullOrWhiteSpace(authorization.Substring(7));
}

set-variable.value:
@{
var jwt = context.Variables.ContainsKey("mosaic-validated-token") ? context.Variables["mosaic-validated-token"] as Jwt : null;
if (jwt == null || jwt.Claims == null || !jwt.Claims.ContainsKey("oid")) { return ""; }
var values = jwt.Claims["oid"];
if (values == null || values.Length != 1 || String.IsNullOrWhiteSpace(values[0])) { return ""; }
return values[0].ToLowerInvariant();
}

