@{
var jwt = context.Variables.ContainsKey("mosaic-validated-token") ? context.Variables["mosaic-validated-token"] as Jwt : null;
if (jwt == null || jwt.Claims == null || !jwt.Claims.ContainsKey("oid")) { return ""; }
var objects = jwt.Claims["oid"];
if (objects == null || objects.Length != 1 || String.IsNullOrWhiteSpace(objects[0])) { return ""; }
var oid = objects[0];
var cc = (string)context.Variables["mosaic-cc"];
bool delegated = false;
bool application = false;
bool hasRealScopes = false;
if (jwt.Claims.ContainsKey("scp")) {
    var scopes = jwt.Claims["scp"];
    if (scopes != null && scopes.Length == 1 && scopes[0] != null) {
        foreach (var scope in scopes[0].Split(' ')) {
            if (String.IsNullOrWhiteSpace(scope) || scope == "/") { continue; }
            hasRealScopes = true;
            if (String.Equals(scope, "Models.Invoke", StringComparison.Ordinal)) { delegated = true; }
        }
    }
}
if (!hasRealScopes && jwt.Claims.ContainsKey("roles")) {
    var roles = jwt.Claims["roles"];
    application = roles != null && roles.Contains("Models.Invoke.Application");
}
if (delegated && String.Equals(oid, "00000001-3333-3333-3333-333333333333", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "sales.emea")) { return "3d7abb22194627137690dc4329c3f475e34c9c7009ad3844003942e743294467|sales.emea"; }
if (delegated && String.Equals(oid, "00000001-3333-3333-3333-333333333333", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "research")) { return "4c9af819b759b8e9dfc7e64407a727a42e576450a91bfa82d5951005521bc5d1|research"; }
if (delegated && String.Equals(oid, "00000001-3333-3333-3333-333333333333", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "general")) { return "82d6717d52e846faa8a5a830f974695f21d0ff719cf9bda91e0caf223bd29a6b|general"; }
if (delegated && String.Equals(oid, "00000004-3333-3333-3333-333333333333", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "research")) { return "1e48c4bfb436743094bbb70de287bcd0bbdac045434f569c1472eaa769a05638|research"; }
if (delegated && String.Equals(oid, "00000005-3333-3333-3333-333333333333", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "sales.emea")) { return "255687aa0a2718c6acca91305347e0d67cb1be1971e3aa2c41d79797509d581c|sales.emea"; }
var groups = jwt.Claims.ContainsKey("groups") ? jwt.Claims["groups"] : null;
if ((delegated || application) && groups != null) {
    foreach (var group in groups) {
        if (String.Equals(group, "00000006-aaaa-aaaa-aaaa-aaaaaaaaaaaa", StringComparison.OrdinalIgnoreCase) && (cc == "" || cc == "research")) { return "2e64af47fc5a01b66e27779873345ab17e711fb02cf7b5c8177a1a0e51420c89|research"; }
    }
}
return "";
}

