when.condition:
@{
if (!String.IsNullOrEmpty((string)context.Variables["mosaic-token-grant"])) { return false; }
var jwt = context.Variables.ContainsKey("mosaic-validated-token") ? context.Variables["mosaic-validated-token"] as Jwt : null;
if (jwt == null || jwt.Claims == null) { return false; }
if (jwt.Claims.ContainsKey("hasgroups")) { return true; }
try {
    if (!jwt.Claims.ContainsKey("_claim_names")) { return false; }
    var values = jwt.Claims["_claim_names"];
    if (values == null) { return false; }
    foreach (var value in values) {
        if (value != null && value.IndexOf("groups", StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
    }
} catch { return false; }
return false;
}

set-variable.value:
@{
var code = (string)context.Variables["mosaic-cost-center"];
if (code == "general") { return "costCenter-general"; }
if (code == "research") { return "costCenter-research"; }
if (code == "sales.emea") { return "costCenter-sales"; }
return "";
}

