when.condition:
@{
var blocked = "{{mosaic-blocked-cost-centers}}";
var key = (string)context.Variables["mosaic-budget-key"];
return key != "" && ("," + blocked + ",").Contains("," + key + ",");
}

@{
if (!(context.Operation.Id == "responses")) { return false; }
if (context.Request.Body == null) { return true; }
try {
    var body = context.Request.Body.As<JObject>(preserveContent: true);
    var model = body == null ? null : body["model"];
    return model == null || model.Type != JTokenType.String ||
        !String.Equals((string)model, "gpt-4o-prod", StringComparison.Ordinal);
} catch { return true; }
}
